import { convert, examples, MAX_BYTES } from './converter.js';
const $=id=>document.getElementById(id);
let result=null,timer,revision=0;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,3500);}
function invalidate(){revision++;result=null;$('report-items').replaceChildren();$('error').textContent='';$('output').value='';$('report').hidden=true;$('error').hidden=true;$('review').checked=false;$('copy').disabled=true;$('download').disabled=true;$('output-label').textContent='AWAITING INPUT';$('output-status').textContent='Convert to generate a new result';$('target-label').textContent=$('target').value.toUpperCase()+' OUTPUT';}
function updateExport(){const allowed=result&&(!result.review||$('review').checked);$('copy').disabled=!allowed;$('download').disabled=!allowed;}
function sample(mode){$('mode').value=mode;$('format').disabled=mode==='json';$('input').value=examples[mode];$('source').value='windows';$('target').value='macos';invalidate();$('input-status').textContent='Sample loaded · no real credentials';}
function route(){let id=location.hash.slice(1)||'converter';if(!['converter','templates','security','guide'].includes(id))id='converter';document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==id);document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.hash==='#'+id));$('page-name').textContent={converter:'Converter',templates:'Starter configs',security:'Security',guide:'Migration guide'}[id];}
window.addEventListener('hashchange',route);route();
$('example').addEventListener('click',()=>sample($('mode').value));
document.querySelectorAll('.template').forEach(b=>b.addEventListener('click',()=>{sample(b.dataset.mode);location.hash='converter';}));
for(const id of ['input','source','target','username','format','redact']) $(id).addEventListener('input',invalidate);
$('input').addEventListener('input',()=>{$('input-status').textContent=`${new TextEncoder().encode($('input').value).length.toLocaleString()} bytes · strict JSON`;});
$('mode').addEventListener('change',()=>{$('format').disabled=$('mode').value==='json';invalidate();});
$('clear').addEventListener('click',()=>{$('input').value='';invalidate();$('input-status').textContent='Configuration cleared';});
$('import').addEventListener('click',()=>$('file').click());
$('file').addEventListener('change',async()=>{const file=$('file').files[0];if(!file)return;invalidate();const importRevision=revision;try{if(file.size>MAX_BYTES)throw Error('File exceeds the 256 KB limit.');const text=await file.text();if(importRevision!==revision)return;$('input').value=text;$('input-status').textContent='File imported · processed locally';}catch(e){$('error').textContent=e.message;$('error').hidden=false;}$('file').value='';});
$('convert').addEventListener('click',()=>{invalidate();try{result=convert($('input').value,{mode:$('mode').value,source:$('source').value,target:$('target').value,username:$('username').value,format:$('mode').value==='json'?'preserve':$('format').value,redact:$('redact').checked});$('output').value=result.output;$('output-label').textContent=result.review?'REVIEW NEEDED':'CONVERTED';$('output-status').textContent=`${result.changes.length} changes · ${result.issues.filter(i=>i.level==='review').length} review items`;$('report-count').textContent=result.servers?`${result.servers} server${result.servers===1?'':'s'}`:'JSON path migration';$('report-summary').textContent=result.review?'Review the items below before enabling copy or export. Paths and dependencies have not been verified on your target device.':'Conversion complete. Check that target paths exist and install the required dependencies before use.';$('report-items').replaceChildren();for(const item of [...result.changes.map(c=>({...c,level:'change'})),...result.issues]){const row=document.createElement('div');row.className='report-item';const tag=document.createElement('span');tag.className='report-tag '+item.level;tag.textContent=item.level.toUpperCase();const body=document.createElement('div');const path=document.createElement('code');path.textContent=item.path;const msg=document.createElement('span');msg.textContent=item.message;body.append(path,msg);row.append(tag,body);$('report-items').append(row);}$('report').hidden=false;$('review-row').hidden=!result.review;updateExport();}catch(e){$('error').textContent=e.message;$('error').hidden=false;}});
$('review').addEventListener('change',updateExport);
$('copy').addEventListener('click',async()=>{if(!result||$('copy').disabled)return;try{await navigator.clipboard.writeText(result.output);toast('Configuration copied. Keep sensitive output private.');}catch{toast('Clipboard unavailable. Select and copy the output manually.');}});
$('download').addEventListener('click',()=>{if(!result||$('download').disabled)return;const url=URL.createObjectURL(new Blob([result.output+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`portbridge-${$('target').value}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('JSON exported. Review it before adding it to your app.');});
